export const i18n = new I18n(translations);
i18n.enableFallback = true;
i18n.defaultLocale = "en";

// ✅ semplice event emitter per forzare il re-render quando cambia la lingua
const _langListeners = new Set();

export function subscribeLanguageChange(cb) {
  if (typeof cb !== "function") return () => {};
  _langListeners.add(cb);
  return () => _langListeners.delete(cb);
}

function normalizeLocaleTag(tag) {
  if (!tag) return "en";
  return String(tag).split(/[-_]/)[0].toLowerCase();
}

function mapToSupported(code) {
  let c = normalizeLocaleTag(code);

  // mapping varianti comuni -> base
  // pt-BR / pt-PT -> pt
  if (c === "pt") return "pt";
  // zh-Hans / zh-Hant -> zh
  if (c === "zh") return "zh";

  // legacy iOS:
  if (c === "iw") c = "he"; // Hebrew
  if (c === "in") c = "id"; // Indonesian

  if (SUPPORTED_CODES.has(c)) return c;
  return "en";
}

async function applyRtlForLanguage(lang) {
  // RTL per arabo/urdu/persiano/ebraico
  const shouldRtl = lang === "ar" || lang === "ur" || lang === "fa" || lang === "he";
  try {
    if (I18nManager.isRTL !== shouldRtl) {
      // in RN spesso richiede reload per applicarsi al 100%, ma così non rompiamo nulla
      I18nManager.allowRTL(shouldRtl);
      I18nManager.forceRTL(shouldRtl);
    }
  } catch {}
}

export async function initLanguage() {
  const stored = await AsyncStorage.getItem(STORAGE_KEY);
  if (stored) {
    const lang = mapToSupported(stored);
    i18n.locale = lang;
    await applyRtlForLanguage(lang);
    return lang;
  }

  const deviceTag =
    Localization.locale || (Localization.getLocales?.()[0]?.languageTag ?? "en");

  const lang = mapToSupported(deviceTag);
  i18n.locale = lang;
  await applyRtlForLanguage(lang);
  return lang;
}

export async function setLanguage(lang) {
  const normalized = mapToSupported(lang);
  i18n.locale = normalized;
  await AsyncStorage.setItem(STORAGE_KEY, normalized);
  await applyRtlForLanguage(normalized);

  // Notifica i listener (es. componenti UI) per aggiornare le traduzioni a schermo
  try {
    _langListeners.forEach((fn) => {
    try { fn(normalized); } catch {}
    });
  } catch {}

  return normalized;
}

export function getLanguage() {
  return mapToSupported(i18n.locale);
}

export function t(key, options) {
  return i18n.t(key, options);
}